package in.gov.moes.ncpor.polarops.model;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Data @Builder @NoArgsConstructor @AllArgsConstructor @Entity @Table(name="mission_assignments")
public class MissionAssignment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="mission_id") private Mission mission; @ManyToOne @JoinColumn(name="team_id") private MissionTeam team; @ManyToOne(optional=false) @JoinColumn(name="personnel_id") private Personnel personnel; private String title; @Column(length=2000) private String description; private Double targetValue; private Double completedValue; private String unit; private String priority; private String status; private LocalDate startDate; private LocalDate deadline; private String targetZone; private LocalDateTime createdAt; private LocalDateTime updatedAt; @Transient public Double getProgressPercent(){ return targetValue == null || targetValue <= 0 ? null : Math.min(100d,(completedValue == null ? 0d:completedValue)*100d/targetValue); } }
